1	// pattern: Imperative Shell
2	//
3	//! Blob garbage collection.
4	//!
5	//! A periodic background task that reclaims blobs no other part of the system needs. Blob
6	//! ownership is per-account (`blob_owners`, V039) over globally content-addressed bytes, so the
7	//! collector works reference-by-reference and touches the shared file only when the last owner
8	//! is gone. It runs in two phases on each pass:
9	//!
10	//! 1. **Reconcile** — for every account that owns a blob reference *or has a repo*, recompute
11	//!    which blob CIDs its records actually reference (by walking the MST) and write that truth
12	//!    back to `blob_owners`: referenced blobs get a permanent ownership row (`ref_count` set,
13	//!    `temp_until` cleared — created on the spot if the account references a stored blob it
14	//!    never uploaded, which also heals pre-V039 rows that credited only the first uploader);
15	//!    a reference that has lost its last record is *released* — its grace clock starts.
16	//! 2. **Sweep** — delete every ownership row whose grace period has expired and which the
17	//!    account no longer references (`temp_until < now AND ref_count = 0`); when a CID's last
18	//!    ownership row goes, delete the physical metadata row and the filesystem file.
19	//!
20	//! Recomputing references from the MST each pass makes the collector authoritative rather than
21	//! trusting an incrementally maintained counter: a blob that is still reachable from any repo
22	//! record is never deleted, and a blob that fell out of every record is eventually collected
23	//! even if some earlier decrement was missed. The grace period means a reference is only ever
24	//! expired on a *later* pass than the one that released it, leaving a window for in-flight
25	//! uploads and writes.
26	
27	use std::collections::HashMap;
28	use std::time::Duration;
29	
30	use tokio::task::JoinHandle;
31	
32	use crate::app::AppState;
33	use crate::blob_store;
34	use crate::db::accounts;
35	use crate::db::blobs;
36	use crate::db::blocks::SqliteBlockStore;
37	use repo_engine::{Cid, Repository};
38	
39	/// Records read per page when walking a collection to collect blob references.
40	const RECORD_PAGE_SIZE: usize = 100;
41	
42	/// Errors that can abort garbage collection for a single account.
43	///
44	/// A failure here is logged and the offending account is skipped; it never aborts the whole
45	/// pass or the background task.
46	#[derive(Debug, thiserror::Error)]
47	pub enum GcError {
48	    #[error("database error: {0}")]
49	    Db(#[from] sqlx::Error),
50	    #[error("repo error: {0}")]
51	    Repo(String),
52	    #[error("blob store error: {0}")]
53	    BlobStore(String),
54	}
55	
56	/// Tally of what one garbage-collection pass did, for logging and tests.
57	#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
58	pub struct GcStats {
59	    /// Ownership rows confirmed still referenced and (re)marked permanent (or newly adopted).
60	    pub reconciled: u64,
61	    /// Ownership rows that lost their last reference this pass and started their grace clock.
62	    pub released: u64,
63	    /// Expired ownership rows removed this pass.
64	    pub expired: u64,
65	    /// Physical blobs deleted (filesystem file + SQLite row) after their last owner expired.
66	    pub deleted: u64,
67	    /// Accounts or blobs skipped due to an error.
68	    pub errors: u64,
69	}
70	
71	/// Spawn the periodic blob garbage collector.
72	///
73	/// The first interval tick is consumed without running GC, so the server does not perform a
74	/// full repo scan during startup; the first pass runs one `interval` after boot. The task
75	/// loops for the life of the process and is dropped on shutdown.
76	pub fn spawn_blob_gc(state: AppState, interval: Duration) -> JoinHandle<()> {
77	    tokio::spawn(async move {
78	        let mut ticker = tokio::time::interval(interval);
79	        // `interval`'s first tick fires immediately — skip it so GC doesn't run mid-boot.
80	        ticker.tick().await;
81	        loop {
82	            ticker.tick().await;
83	            run_blob_gc(&state).await;
84	        }
85	    })
86	}
87	
88	/// Run a single garbage-collection pass over every account that owns blobs or has a repo.
89	///
90	/// Resilient by design: an error reconciling one account, or deleting one blob, is logged and
91	/// counted in [`GcStats::errors`] but does not stop the pass. Reconciling (which adopts
92	/// referenced-but-unowned blobs into `blob_owners`) always runs before the sweep, so a
93	/// reference discovered this pass is protected before any file can be reclaimed.
94	pub async fn run_blob_gc(state: &AppState) -> GcStats {
95	    let mut stats = GcStats::default();
96	
97	    // Phase 1: reconcile each account's blob references against its MST.
98	    let candidate_dids = match blobs::list_gc_candidate_dids(&state.db).await {
99	        Ok(dids) => dids,
100	        Err(e) => {
101	            tracing::error!(error = %e, "blob GC: failed to list candidate accounts; skipping pass");
102	            return stats;
103	        }
104	    };
105	    for did in candidate_dids {
106	        match reconcile_account(state, &did).await {
107	            Ok((reconciled, released)) => {
108	                stats.reconciled += reconciled;
109	                stats.released += released;
110	            }
111	            Err(e) => {
112	                stats.errors += 1;
113	                tracing::warn!(error = %e, did = %did, "blob GC: reconcile failed; account skipped");
114	            }
115	        }
116	    }
117	
118	    // Phase 2: sweep ownership rows whose grace period has expired; reclaim the physical row
119	    // and file once a CID's last owner is gone.
120	    match blobs::list_expired_temp_owners(&state.db).await {
121	        Ok(expired) => {
122	            for (did, cid) in expired {
123	                match sweep_expired_owner(state, &did, &cid).await {
124	                    Ok((owner_expired, file_deleted)) => {
125	                        stats.expired += u64::from(owner_expired);
126	                        stats.deleted += u64::from(file_deleted);
127	                    }
128	                    Err(e) => {
129	                        stats.errors += 1;
130	                        tracing::warn!(error = %e, did = %did, cid = %cid, "blob GC: failed to sweep expired blob reference");
131	                    }
132	                }
133	            }
134	        }
135	        Err(e) => {
136	            // The whole expiry sweep was skipped, so this pass did not complete — return
137	            // without recording, leaving the last-run timestamp stale (the operator's
138	            // signal), matching firehose_gc's failed-pass posture.
139	            tracing::error!(error = %e, "blob GC: failed to list expired blob references");
140	            return stats;
141	        }
142	    }
143	
144	    if stats.deleted > 0 || stats.expired > 0 || stats.released > 0 || stats.errors > 0 {
145	        tracing::info!(
146	            reconciled = stats.reconciled,
147	            released = stats.released,
148	            expired = stats.expired,
149	            deleted = stats.deleted,
150	            errors = stats.errors,
151	            "blob GC pass complete"
152	        );
153	    } else {
154	        tracing::debug!(
155	            reconciled = stats.reconciled,
156	            "blob GC pass complete (nothing to collect)"
157	        );
158	    }
159	
160	    // A failed pass (the early returns above) deliberately does not touch the
161	    // timestamp: a stale `blob_gc_last_run_timestamp` is the operator's signal that
162	    // sweeps are not completing.
163	    state.metrics.blob_gc_swept.add(stats.deleted, &[]);
164	    state
165	        .metrics
166	        .blob_gc_last_run_timestamp
167	        .record(crate::metrics::unix_now(), &[]);
168	    state
169	        .sweeps
170	        .record_blob_gc(crate::sweep_status::SweepRun::now(stats.deleted));
171	
172	    stats
173	}
174	
175	/// Reconcile one account's blob ownership rows against the references in its repo.
176	///
177	/// Returns `(reconciled, released)`: the number of ownership rows (re)marked permanent —
178	/// created on the spot when the account references a stored blob it has no row for — and the
179	/// number that transitioned from permanent to temporary (lost their last reference) this pass.
180	async fn reconcile_account(state: &AppState, did: &str) -> Result<(u64, u64), GcError> {
181	    let referenced = collect_referenced_blob_cids(state, did).await?;
182	    let owned = blobs::list_owned_blobs(&state.db, did).await?;
183	
184	    // A fresh grace deadline for references that lose their last record this pass.
185	    // Format must match SQLite's `datetime('now')` (`YYYY-MM-DD HH:MM:SS`): `temp_until` is
186	    // stored as TEXT and compared lexicographically, so a `T`/`Z` ISO form would sort after
187	    // the space-separated form and hide same-day deadlines from `list_expired_temp_owners`.
188	    let grace =
189	        chrono::Utc::now() + chrono::Duration::seconds(state.config.blobs.temp_ttl_secs as i64);
190	    let grace_str = grace.format("%Y-%m-%d %H:%M:%S").to_string();
191	
192	    let mut reconciled = 0;
193	    let mut released = 0;
194	
195	    // Every CID this account's records reference: pin (or adopt) it permanent with the true
196	    // count. Non-blob CID links in the reference walk are no-ops (no physical `blobs` row).
197	    for (cid, n) in &referenced {
198	        if blobs::upsert_owner_referenced(&state.db, did, cid, *n).await? {
199	            reconciled += 1;
200	        }
201	    }
202	
203	    // Every owned reference no record uses any longer: if it was permanent, start its grace
204	    // clock; a reference already counting down (temp_until set) is left to expire.
205	    for owner in owned {
206	        if !referenced.contains_key(&owner.cid)
207	            && blobs::release_owner(&state.db, did, &owner.cid, &grace_str).await?
208	        {
209	            released += 1;
210	        }
211	    }
212	
213	    Ok((reconciled, released))
214	}
215	
216	/// Walk an account's repo and count how many records reference each blob CID.
217	///
218	/// Returns an empty map when the account has no repo root (nothing can reference a blob).
219	async fn collect_referenced_blob_cids(
220	    state: &AppState,
221	    did: &str,
222	) -> Result<HashMap<String, i64>, GcError> {
223	    let mut counts: HashMap<String, i64> = HashMap::new();
224	
225	    let root_str = match accounts::get_repo_root_cid(&state.db, did).await? {
226	        Some(root) => root,
227	        None => return Ok(counts),
228	    };
229	    let root_cid = Cid::try_from(root_str.as_str())
230	        .map_err(|e| GcError::Repo(format!("invalid root CID {root_str}: {e}")))?;
231	
232	    let store = SqliteBlockStore::new(state.db.clone(), did.to_string());
233	    let mut repo = Repository::open(store, root_cid)
234	        .await
235	        .map_err(|e| GcError::Repo(format!("open repo: {e}")))?;
236	
237	    let collections = repo_engine::list_collections(&mut repo)
238	        .await
239	        .map_err(|e| GcError::Repo(format!("list collections: {e}")))?;
240	
241	    for collection in collections {
242	        let mut cursor: Option<String> = None;
243	        loop {
244	            let page = repo_engine::list_records_json(
245	                &mut repo,
246	                &collection,
247	                RECORD_PAGE_SIZE,
248	                cursor.as_deref(),
249	                false,
250	            )
251	            .await
252	            .map_err(|e| GcError::Repo(format!("list records: {e}")))?;
253	
254	            for record in &page.records {
255	                collect_blob_links(&record.value, &mut counts);
256	            }
257	
258	            match page.cursor {
259	                Some(next) => cursor = Some(next),
260	                None => break,
261	            }
262	        }
263	    }
264	
265	    Ok(counts)
266	}
267	
268	/// Recursively collect CID-link strings from a record's JSON, tallying each occurrence.
269	///
270	/// A CID link is encoded as a single-key object `{"$link": "<cid>"}` (see
271	/// [`repo_engine::record_value_to_json`]); a blob reference embeds one under its `ref` field.
272	/// Non-blob links are collected too, but they simply never match a row in the `blobs` table,
273	/// so they are harmless noise to the caller.
274	fn collect_blob_links(value: &serde_json::Value, out: &mut HashMap<String, i64>) {
275	    use serde_json::Value;
276	    match value {
277	        Value::Object(map) => {
278	            if map.len() == 1 {
279	                if let Some(Value::String(cid)) = map.get("$link") {
280	                    *out.entry(cid.clone()).or_insert(0) += 1;
281	                    return;
282	                }
283	            }
284	            for v in map.values() {
285	                collect_blob_links(v, out);
286	            }
287	        }
288	        Value::Array(items) => {
289	            for item in items {
290	                collect_blob_links(item, out);
291	            }
292	        }
293	        _ => {}
294	    }
295	}
296	
297	/// Sweep one expired ownership row, reclaiming the physical blob when it was the last owner.
298	///
299	/// Returns `(owner_expired, file_deleted)`. The ownership delete re-checks the expiry
300	/// conditions (a reference re-pinned since the candidate scan survives), and the physical
301	/// delete checks for remaining owners in the same statement that removes the row, so a CID
302	/// another account still owns is never touched. The file is unlinked only after its row is
303	/// gone: the DB is the source of truth, and that ordering's failure mode is an orphaned file
304	/// (a benign leak, logged), never a live row pointing at deleted bytes.
305	async fn sweep_expired_owner(
306	    state: &AppState,
307	    did: &str,
308	    cid: &str,
309	) -> Result<(bool, bool), GcError> {
310	    if !blobs::delete_expired_owner(&state.db, did, cid).await? {
311	        return Ok((false, false));
312	    }
313	    tracing::debug!(cid = %cid, did = %did, "blob GC: expired blob reference removed");
314	
315	    let Some(storage_path) = blobs::delete_blob_if_unowned(&state.db, cid).await? else {
316	        // Another account still owns the CID; its bytes stay.
317	        return Ok((true, false));
318	    };
319	
320	    let existed = blob_store::delete_blob_file(&state.config.data_dir, &storage_path)
321	        .await
322	        .map_err(|e| GcError::BlobStore(format!("delete blob file: {e}")))?;
323	    if !existed {
324	        tracing::warn!(
325	            cid = %cid,
326	            path = %storage_path,
327	            "blob GC: file already absent on disk; row already removed"
328	        );
329	    }
330	
331	    tracing::info!(cid = %cid, "blob GC: deleted unreferenced blob");
332	    Ok((true, true))
333	}
