344	    #[test]
345	    fn collect_blob_links_finds_nested_and_counts_occurrences() {
346	        let record = json!({
347	            "$type": "app.bsky.feed.post",
348	            "text": "hi",
349	            "embed": {
350	                "$type": "app.bsky.embed.images",
351	                "images": [
352	                    { "image": { "$type": "blob", "ref": { "$link": "bafkreiAAA" }, "mimeType": "image/png", "size": 10 } },
353	                    { "image": { "$type": "blob", "ref": { "$link": "bafkreiBBB" }, "mimeType": "image/png", "size": 20 } },
354	                    { "image": { "$type": "blob", "ref": { "$link": "bafkreiAAA" }, "mimeType": "image/png", "size": 10 } }
355	                ]
356	            }
357	        });
358	        let mut out = HashMap::new();
359	        collect_blob_links(&record, &mut out);
360	
361	        assert_eq!(out.get("bafkreiAAA"), Some(&2));
362	        assert_eq!(out.get("bafkreiBBB"), Some(&1));
363	        assert_eq!(out.len(), 2);
364	    }
