402	    /// Store `content` as a blob on disk and insert its metadata row with the given
403	    /// `temp_until`. Returns the blob CID.
404	    async fn add_blob(state: &AppState, did: &str, content: &[u8], temp_until: &str) -> String {
405	        let stored =
406	            blob_store::store_blob(&state.config.data_dir, content, "application/octet-stream")
407	                .await
408	                .unwrap();
409	        blobs::insert_blob(
410	            &state.db,
411	            &stored.cid,
412	            did,
413	            &stored.mime_type,
414	            stored.size_bytes as i64,
415	            &stored.storage_path,
416	            temp_until,
417	        )
418	        .await
419	        .unwrap();
420	        stored.cid
421	    }
