496	    #[tokio::test]
497	    async fn gc_keeps_referenced_blob_and_deletes_unreferenced() {
498	        let (state, _dir) = gc_state().await;
499	        let did = "did:plc:gckeep";
500	        seed_account_with_repo(&state.db, did).await;
501	
502	        // Both blobs start expired; the referenced one must be rescued before the sweep.
503	        let referenced = add_blob(
504	            &state,
505	            did,
506	            b"referenced blob bytes",
507	            "2020-01-01T00:00:00Z",
508	        )
509	        .await;
510	        let orphan = add_blob(&state, did, b"orphan blob bytes", "2020-01-01T00:00:00Z").await;
511	
512	        write_record(
513	            &state,
514	            did,
515	            "app.bsky.feed.post/1",
516	            blob_record(&referenced),
517	        )
518	        .await;
519	
520	        let stats = run_blob_gc(&state).await;
521	        assert_eq!(stats.deleted, 1, "exactly the orphan blob is deleted");
522	        assert_eq!(stats.expired, 1, "only the orphan's ownership row expired");
523	        assert_eq!(stats.errors, 0);
524	
525	        // The sweep's instruments fire: the deletion is counted and the pass is timestamped.
526	        let rendered = state.metrics.render().unwrap().unwrap();
527	        assert!(
528	            rendered.contains("blob_gc_swept_total"),
529	            "missing blob_gc_swept_total in:\n{rendered}"
530	        );
