    // repo root at B's root CID is a structurally valid CID whose block A cannot load —
    // `Repository::open` fails and `reconcile_account` returns Err, exactly the production
    // shape (a repo walk that errors for any reason).
    let b_root = accounts::get_repo_root_cid(&state.db, did_b)
        .await
        .unwrap()
        .unwrap();
    sqlx::query("UPDATE accounts SET repo_root_cid = ? WHERE did = ?")
        .bind(&b_root)
        .bind(did_a)
        .execute(&state.db)
        .await
        .unwrap();

