3	//! Readable last-run state for the periodic background sweeps.
4	//!
5	//! The OTel gauges in `metrics.rs` are write-only from inside the process — only a
6	//! Prometheus scrape observes them. The operator health endpoint
7	//! (`GET /v1/admin/health`) reports the same "is the sweep alive" signal as JSON, so each
8	//! sweep records its completion here, in the same place it writes its gauges, and the
9	//! route reads it back. Unlike the gauges this works with `[telemetry] metrics_enabled`
10	//! off.
11	//!
12	//! The recording sites share the sweeps' failure posture: a failed pass records nothing,
13	//! so a stale (or absent) [`SweepRun`] is the operator's signal that passes are not
14	//! completing — never record unconditionally at loop top.
15	
16	use std::sync::RwLock;
17	
18	/// One completed sweep pass.
19	#[derive(Debug, Clone, Copy)]
20	pub struct SweepRun {
21	    /// Unix seconds when the pass completed.
22	    pub completed_at: i64,
23	    /// Rows/files acted on by the pass (deleted blobs, pruned seq rows, reaped accounts,
24	    /// expired claim attempts).
25	    pub swept: u64,
26	    /// Items the pass skipped due to an error. A completed pass with `errors > 0` did run,
27	    /// but did not do its whole job — the distinction a stale `completed_at` alone cannot
28	    /// draw between "one subject is broken" and "the sweep is dead". Sweeps that have no
29	    /// per-item error path leave this `0`.
30	    pub errors: u64,
31	}
32	
33	impl SweepRun {
34	    /// A pass completing now, having swept `swept` items with no errors.
35	    pub fn now(swept: u64) -> Self {
36	        Self::now_with_errors(swept, 0)
37	    }
38	
39	    /// A pass completing now, having swept `swept` items and skipped `errors` on failures.
40	    pub fn now_with_errors(swept: u64, errors: u64) -> Self {
41	        Self {
42	            completed_at: chrono::Utc::now().timestamp(),
43	            swept,
44	            errors,
45	        }
46	    }
47	}
48	
49	/// Last completed pass per periodic sweep. Every field is `None` until that sweep's first
50	/// completed pass after boot (each first pass runs one full interval after startup).
51	#[derive(Debug, Default, Clone, Copy)]
52	pub struct SweepSnapshot {
53	    pub blob_gc: Option<SweepRun>,
54	    /// The blob mirror is a replicator rather than a reclaimer, but shares the sweep
55	    /// posture: `swept` counts bucket objects synced (uploads + deletes), and a stale
56	    /// pass is the alarm.
57	    pub blob_mirror: Option<SweepRun>,
58	    /// The blob scrub is a verifier rather than a reclaimer: `swept` counts integrity
59	    /// problems flagged this pass (missing files, hash/size mismatches, orphan files) that
60	    /// were not auto-healed — the operator alarm count. A stale pass is still the alarm.
61	    pub blob_scrub: Option<SweepRun>,
62	    pub firehose_gc: Option<SweepRun>,
63	    pub account_reaper: Option<SweepRun>,
64	    pub agent_claim_sweep: Option<SweepRun>,
65	    pub admin_nonce_sweep: Option<SweepRun>,
66	    /// The labeler watcher is a poller rather than a reclaimer, but shares the sweep
67	    /// posture: `swept` counts label rows changed, and a stale pass is the alarm.
68	    pub labeler_watch: Option<SweepRun>,
69	}
70	
71	/// Shared readable sweep state; one lives in `AppState` for the process lifetime.
72	#[derive(Debug, Default)]
73	pub struct SweepStatus {
74	    inner: RwLock<SweepSnapshot>,
75	}
76	
77	impl SweepStatus {
78	    pub fn record_blob_gc(&self, run: SweepRun) {
79	        self.write().blob_gc = Some(run);
80	    }
81	
82	    pub fn record_blob_mirror(&self, run: SweepRun) {
83	        self.write().blob_mirror = Some(run);
84	    }
85	
86	    pub fn record_blob_scrub(&self, run: SweepRun) {
87	        self.write().blob_scrub = Some(run);
88	    }
89	
90	    pub fn record_firehose_gc(&self, run: SweepRun) {
91	        self.write().firehose_gc = Some(run);
92	    }
93	
94	    pub fn record_account_reaper(&self, run: SweepRun) {
95	        self.write().account_reaper = Some(run);
96	    }
97	
98	    pub fn record_agent_claim_sweep(&self, run: SweepRun) {
99	        self.write().agent_claim_sweep = Some(run);
100	    }
101	
102	    pub fn record_admin_nonce_sweep(&self, run: SweepRun) {
103	        self.write().admin_nonce_sweep = Some(run);
104	    }
105	
106	    pub fn record_labeler_watch(&self, run: SweepRun) {
107	        self.write().labeler_watch = Some(run);
108	    }
109	
110	    pub fn snapshot(&self) -> SweepSnapshot {
111	        // A poisoned lock means a writer panicked mid-assignment of a Copy value — the
112	        // data cannot be torn, so read through the poison rather than propagating a panic
113	        // into the health endpoint.
114	        match self.inner.read() {
115	            Ok(guard) => *guard,
116	            Err(poisoned) => *poisoned.into_inner(),
117	        }
118	    }
119	
120	    fn write(&self) -> std::sync::RwLockWriteGuard<'_, SweepSnapshot> {
121	        match self.inner.write() {
122	            Ok(guard) => guard,
123	            Err(poisoned) => poisoned.into_inner(),
124	        }
125	    }
126	}
